## Teljes egyfájlos HTML implementáció

```html
<!DOCTYPE html>
<html lang="hu">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>ChainOfThought Component</title>
  <style>
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      font-family: system-ui, -apple-system, sans-serif;
      background: #ffffff;
      color: #0a0a0a;
      line-height: 1.5;
    }

    :root {
      --background: #ffffff;
      --foreground: #0a0a0a;
      --muted: #f1f5f9;
      --muted-foreground: #64748b;
      --border: #e2e8f0;
      --popover: #ffffff;
      --popover-foreground: #0a0a0a;
    }

    .chain-of-thought {
      width: 100%;
      space-y: 1rem;
    }

    .chain-of-thought-header {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      cursor: pointer;
      color: var(--muted-foreground);
      transition: color 0.2s;
      padding: 0.5rem 0;
      width: 100%;
      border: none;
      background: none;
      font-size: 0.875rem;
    }

    .chain-of-thought-header:hover {
      color: var(--foreground);
    }

    .chain-of-thought-header:focus {
      outline: 2px solid var(--foreground);
      outline-offset: 2px;
    }

    .chain-of-thought-content {
      margin-top: 0.5rem;
      space-y: 0.75rem;
      outline: none;
    }

    .chain-of-thought-content[data-state="closed"] {
      display: none;
    }

    .chain-of-thought-content[data-state="open"] {
      display: block;
      animation: fade-in-0 0.2s ease-out, slide-in-from-top-2 0.2s ease-out;
    }

    @keyframes fade-in-0 {
      from { opacity: 0; }
      to { opacity: 1; }
    }

    @keyframes slide-in-from-top-2 {
      from { transform: translateY(-0.5rem); }
      to { transform: translateY(0); }
    }

    @keyframes fade-out-0 {
      from { opacity: 1; }
      to { opacity: 0; }
    }

    @keyframes slide-out-to-top-2 {
      from { transform: translateY(0); }
      to { transform: translateY(-0.5rem); }
    }

    .chain-of-thought-step {
      display: flex;
      gap: 0.5rem;
      font-size: 0.875rem;
      margin-bottom: 0.75rem;
    }

    .chain-of-thought-step.active {
      color: var(--foreground);
    }

    .chain-of-thought-step.complete,
    .chain-of-thought-step.pending {
      color: var(--muted-foreground);
    }

    .chain-of-thought-step.pending {
      opacity: 0.5;
    }

    .chain-of-thought-step-icon {
      position: relative;
      margin-top: 0.125rem;
    }

    .chain-of-thought-step-icon::after {
      content: '';
      position: absolute;
      top: 1.75rem;
      bottom: 0;
      left: 50%;
      transform: translateX(-50%);
      width: 1px;
      background: var(--border);
    }

    .chain-of-thought-step:last-child .chain-of-thought-step-icon::after {
      display: none;
    }

    .chain-of-thought-step-content {
      flex: 1;
      space-y: 0.5rem;
      overflow: hidden;
    }

    .chain-of-thought-step-description {
      color: var(--muted-foreground);
      font-size: 0.75rem;
    }

    .chain-of-thought-search-results {
      display: flex;
      flex-wrap: wrap;
      gap: 0.5rem;
      margin-top: 0.5rem;
    }

    .chain-of-thought-search-result {
      background: var(--muted);
      border: 1px solid var(--border);
      border-radius: 0.25rem;
      padding: 0.125rem 0.5rem;
      font-size: 0.75rem;
      font-weight: 400;
    }

    .chain-of-thought-image {
      margin-top: 0.5rem;
      space-y: 0.5rem;
    }

    .chain-of-thought-image-content {
      position: relative;
      display: flex;
      max-height: 22rem;
      align-items: center;
      justify-content: center;
      overflow: hidden;
      border-radius: 0.5rem;
      background: var(--muted);
      padding: 0.75rem;
    }

    .chain-of-thought-image-content img {
      max-height: 100%;
      max-width: 100%;
      object-fit: contain;
    }

    .chain-of-thought-image-caption {
      color: var(--muted-foreground);
      font-size: 0.75rem;
    }

    .icon {
      width: 1rem;
      height: 1rem;
    }

    .chevron {
      transition: transform 0.2s;
    }

    .chevron.open {
      transform: rotate(180deg);
    }

    .animate-step {
      animation: fade-in-0 0.3s ease-out, slide-in-from-top-2 0.3s ease-out;
    }

    @media (max-width: 640px) {
      .chain-of-thought-header {
        font-size: 0.8125rem;
      }

      .chain-of-thought-step {
        font-size: 0.8125rem;
      }

      .chain-of-thought-step-description {
        font-size: 0.6875rem;
      }

      .chain-of-thought-search-result {
        font-size: 0.6875rem;
      }
    }
  </style>
</head>
<body>
  <div id="app" style="max-width: 640px; margin: 2rem auto; padding: 0 1rem;"></div>

  <script>
    class ChainOfThought {
      constructor(container, options = {}) {
        this.container = container;
        this.isOpen = options.defaultOpen || false;
        this.onOpenChange = options.onOpenChange;
        this.steps = [];
        this.init();
      }

      init() {
        this.root = document.createElement('div');
        this.root.className = 'chain-of-thought';
        this.root.setAttribute('role', 'region');
        this.root.setAttribute('aria-label', 'AI gondolatmenet');

        this.header = document.createElement('button');
        this.header.className = 'chain-of-thought-header';
        this.header.setAttribute('type', 'button');
        this.header.setAttribute('aria-expanded', this.isOpen);
        this.header.setAttribute('aria-controls', 'cot-content');

        const brainIcon = document.createElementNS('', 'svg');
        brainIcon.setAttribute('class', 'icon');
        brainIcon.setAttribute('viewBox', '0 0 24 24');
        brainIcon.setAttribute('fill', 'none');
        brainIcon.setAttribute('stroke', 'currentColor');
        brainIcon.setAttribute('stroke-width', '2');
        brainIcon.innerHTML = `
          <path d="M9.5 2A2.5 2.5 0 0 1 12 4.5v15a2.5 2.5 0 0 1-4.96.44 2.5 2.5 0 0 1-2.96-3.08 3 3 0 0 1-.34-5.58 2.5 2.5 0 0 1 1.32-4.24 2.5 2.5 0 0 1 1.98-3A2.5 2.5 0 0 1 9.5 2Z"/>
          <path d="M14.5 2A2.5 2.5 0 0 0 12 4.5v15a2.5 2.5 0 0 0 4.96.44 2.5 2.5 0 0 0 2.96-3.08 3 3 0 0 0 .34-5.58 2.5 2.5 0 0 0-1.32-4.24 2.5 2.5 0 0 0-1.98-3A2.5 2.5 0 0 0 14.5 2Z"/>
        `;

        const label = document.createElement('span');
        label.textContent = 'Chain of Thought';
        label.style.flex = '1';
        label.style.textAlign = 'left';

        const chevron = document.createElementNS('', 'svg');
        chevron.setAttribute('class', 'icon chevron');
        chevron.setAttribute('viewBox', '0 0 24 24');
        chevron.setAttribute('fill', 'none');
        chevron.setAttribute('stroke', 'currentColor');
        chevron.setAttribute('stroke-width', '2');
        chevron.innerHTML = '<path d="m6 9 6 6 6-6"/>';

        this.header.appendChild(brainIcon);
        this.header.appendChild(label);
        this.header.appendChild(chevron);

        this.header.addEventListener('click', () => this.toggle());
        this.header.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            this.toggle();
          }
        });

        this.content = document.createElement('div');
        this.content.id = 'cot-content';
        this.content.className = 'chain-of-thought-content';
        this.content.setAttribute('data-state', this.isOpen ? 'open' : 'closed');
        this.content.setAttribute('aria-live', 'polite');

        this.root.appendChild(this.header);
        this.root.appendChild(this.content);
        this.container.appendChild(this.root);
      }

      toggle() {
        this.isOpen = !this.isOpen;
        this.header.setAttribute('aria-expanded', this.isOpen);
        this.content.setAttribute('data-state', this.isOpen ? 'open' : 'closed');
        if (this.onOpenChange) {
          this.onOpenChange(this.isOpen);
        }
      }

      addStep(options) {
        const step = new ChainOfThoughtStep(options);
        this.steps.push(step);
        this.content.appendChild(step.element);
        return step;
      }

      clearSteps() {
        this.steps.forEach(step => step.element.remove());
        this.steps = [];
      }
    }

    class ChainOfThoughtStep {
      constructor(options = {}) {
        this.icon = options.icon || 'dot';
        this.label = options.label || '';
        this.description = options.description || '';
        this.status = options.status || 'complete';
        this.children = options.children || [];

        this.element = document.createElement('div');
        this.element.className = `chain-of-thought-step ${this.status} animate-step`;

        const iconContainer = document.createElement('div');
        iconContainer.className = 'chain-of-thought-step-icon';

        const iconSvg = document.createElementNS('', 'svg');
        iconSvg.setAttribute('class', 'icon');
        iconSvg.setAttribute('viewBox', '0 0 24 24');
        iconSvg.setAttribute('fill', 'currentColor');

        if (this.icon === 'dot') {
          iconSvg.innerHTML = '<circle cx="12" cy="12" r="10"/>';
        } else if (this.icon === 'star') {
          iconSvg.innerHTML = '<path d="m12 2 3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/>';
        } else {
          iconSvg.innerHTML = '<circle cx="12" cy="12" r="10"/>';
        }

        iconContainer.appendChild(iconSvg);

        const content = document.createElement('div');
        content.className = 'chain-of-thought-step-content';

        const labelEl = document.createElement('div');
        labelEl.textContent = this.label;

        content.appendChild(labelEl);

        if (this.description) {
          const descEl = document.createElement('div');
          descEl.className = 'chain-of-thought-step-description';
          descEl.textContent = this.description;
          content.appendChild(descEl);
        }

        if (Array.isArray(this.children) && this.children.length > 0) {
          this.children.forEach(child => {
            if (typeof child === 'string') {
              const textEl = document.createElement('div');
              textEl.textContent = child;
              content.appendChild(textEl);
            } else if (child instanceof HTMLElement) {
              content.appendChild(child);
            }
          });
        }

        this.element.appendChild(iconContainer);
        this.element.appendChild(content);
      }
    }

    class ChainOfThoughtSearchResults {
      constructor(results = []) {
        this.element = document.createElement('div');
        this.element.className = 'chain-of-thought-search-results';

        results.forEach(result => {
          const badge = new ChainOfThoughtSearchResult(result);
          this.element.appendChild(badge.element);
        });
      }
    }

    class ChainOfThoughtSearchResult {
      constructor(text = '') {
        this.element = document.createElement('span');
        this.element.className = 'chain-of-thought-search-result';
        this.element.textContent = text;
      }
    }

    class ChainOfThoughtImage {
      constructor(src, caption = '') {
        this.element = document.createElement('div');
        this.element.className = 'chain-of-thought-image';

        const imageContainer = document.createElement('div');
        imageContainer.className = 'chain-of-thought-image-content';

        const img = document.createElement('img');
        img.src = src;
        img.alt = caption || 'AI kép';

        imageContainer.appendChild(img);
        this.element.appendChild(imageContainer);

        if (caption) {
          const captionEl = document.createElement('p');
          captionEl.className = 'chain-of-thought-image-caption';
          captionEl.textContent = caption;
          this.element.appendChild(captionEl);
        }
      }
    }

    // Példa használat
    const app = document.getElementById('app');
    const cot = new ChainOfThought(app, { defaultOpen: false });

    // 1. lépés
    cot.addStep({
      label: 'Probléma azonosítása',
      description: 'A felhasználó egy AI gondolatmenet vizualizáló komponenst kért.',
      status: 'complete',
      icon: 'dot'
    });

    // 2. lépés
    cot.addStep({
      label: 'Követelmények elemzése',
      description: 'Egyfájlos HTML megoldás, React nélkül, teljes funkcionalitással.',
      status: 'complete',
      icon: 'dot'
    });

    // 3. lépés
    const searchResults = new ChainOfThoughtSearchResults([
      'HTML/CSS/JS',
      'Web Components',
      'Accessibility',
      'Animations'
    ]);
    cot.addStep({
      label: 'Technológiai döntések',
      description: 'Kiválasztott technológiák és megközelítések:',
      status: 'active',
      icon: 'star',
      children: [searchResults.element]
    });

    // 4. lépés
    const imageStep = new ChainOfThoughtImage(
      'data:image/svg+xml;base64,',
      'AI gondolatmenet vizualizáció'
    );
    cot.addStep({
      label: 'Komponens felépítése',
      description: 'A teljes rendszer implementálása egyetlen HTML fájlban.',
      status: 'pending',
      icon: 'dot',
      children: [imageStep.element]
    });
  </script>
</body>
</html>
